        [AtmosphereProperty(VarType.Float, "VariationAmount", minFloat = 0, maxFloat = 1)]
        public AtmosphereProperty<FloatValue> variationAmount;
        /// <summary>
        /// Sets the scale of the height fog variation
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the scale of the height fog variation")]
        [AtmosphereProperty(VarType.Vector3, "VariationTextureScale")]
        public AtmosphereProperty<Vector3Value> variationTextureScale;
        /// <summary>
        /// Sets the movement speed and direction of the height fog variation
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the movement speed and direction of the height fog variation")]
        [AtmosphereProperty(VarType.Vector3, "VariationTextureFlow")]
        public AtmosphereProperty<Vector3Value> variationTextureFlow;

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float time) {
            if (!active) return;
            color.SetValue(ref parameters.fogHeightColor, time);
            falloff.SetValue(ref parameters.fogHeightFalloff, time);
            smoothness.SetValue(ref parameters.fogHeightSmoothness, time);
            baseHeight.SetValue(ref parameters.fogHeightBaseHeight, time);
            density.SetValue(ref parameters.fogHeightDensity, time);
            variationNoise.SetValue(ref parameters.fogHeightVariationNoise, time);
            variationAmount.SetValue(ref parameters.fogHeightVariationAmount, time);
            variationTextureScale.SetValue(ref parameters.fogHeightVariationTextureScale, time);
            variationTextureFlow.SetValue(ref parameters.fogHeightVariationTextureFlow, time);
        }

        public override void ResetToDefaults() {
        }

        public override void CopyModel(AtmosphereModel model) {
                color = model.fogHeightColor;
                falloff = model.fogHeightFalloff;
                smoothness = model.fogHeightSmoothness;
                baseHeight = model.fogHeightBaseHeight;
                density = model.fogHeightDensity;
                variationNoise = model.fogHeightVariationNoise;
                variationAmount = model.fogHeightVariationAmount;
                variationTextureScale = model.fogHeightVariationTextureScale;
                variationTextureFlow = model.fogHeightVariationTextureFlow;
        }

        public override void ApplyAsBiome(AtmosphereParameters parameters, float time, float weight) {
            if (!active || weight == 0) return;
            parameters.fogHeightColor.Lerp(color.GetValue(parameters.fogHeightColor, time), weight);
            parameters.fogHeightFalloff.Lerp(falloff.GetValue(parameters.fogHeightFalloff, time), weight);
            parameters.fogHeightSmoothness.Lerp(smoothness.GetValue(parameters.fogHeightSmoothness, time), weight);
            parameters.fogHeightBaseHeight.Lerp(baseHeight.GetValue(parameters.fogHeightBaseHeight, time), weight);
            parameters.fogHeightDensity.Lerp(density.GetValue(parameters.fogHeightDensity, time), weight);
            parameters.fogHeightVariationNoise.Lerp(variationNoise.GetValue(parameters.fogHeightVariationNoise, time), weight);
            parameters.fogHeightVariationAmount.Lerp(variationAmount.GetValue(parameters.fogHeightVariationAmount, time), weight);
            parameters.fogHeightVariationTextureScale.Lerp(variationTextureScale.GetValue(parameters.fogHeightVariationTextureScale, time), weight);
            parameters.fogHeightVariationTextureFlow.Lerp(variationTextureFlow.GetValue(parameters.fogHeightVariationTextureFlow, time), weight);
        }

        public override void ApplyToModel(AtmosphereModel model) {
             if (!FeatureEnabledGlobally || !active) return;
            if (color.overrideValue)
                model.fogHeightColor = color;
            if (falloff.overrideValue)
                model.fogHeightFalloff = falloff;
            if (smoothness.overrideValue)
                model.fogHeightSmoothness = smoothness;
            if (baseHeight.overrideValue)
                model.fogHeightBaseHeight = baseHeight;
            if (density.overrideValue)
                model.fogHeightDensity = density;
            if (variationNoise.overrideValue)
                model.fogHeightVariationNoise = variationNoise;
            if (variationAmount.overrideValue)
                model.fogHeightVariationAmount = variationAmount;
            if (variationTextureScale.overrideValue)
                model.fogHeightVariationTextureScale = variationTextureScale;
            if (variationTextureFlow.overrideValue)
                model.fogHeightVariationTextureFlow = variationTextureFlow;
        }
    }

    //Base
    [System.Serializable]
    public class FogBaseOverride : AtmosphereOverride
    {
        public override string Title => "Base";
        public override string Category => "Fog";
        public override bool FeatureEnabledGlobally => CozyPreferences.CurrentStyle.UseFogBase;
        public override void ToggleFeature() => CozyPreferences.CurrentStyle.ToggleFogBase();

        /// <summary>
        /// Global multiplier applied to overall fog density.
        /// </summary>
        [CozySearchable]
        [Tooltip("Global multiplier applied to overall fog density.")]
        [AtmosphereProperty(VarType.Float, "DensityMultiplier")]
        public AtmosphereProperty<FloatValue> densityMultiplier;
        /// <summary>
        /// Sets the base elevation height for fog in the background.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the base elevation height for fog in the background.")]
        [AtmosphereProperty(VarType.Float, "Height", minFloat = -1, maxFloat = 1)]
        public AtmosphereProperty<FloatValue> height;
        /// <summary>
        /// Controls the transition smoothness of the fog in the background.
        /// </summary>
        [CozySearchable]
        [Tooltip("Controls the transition smoothness of the fog in the background.")]
        [AtmosphereProperty(VarType.Float, "Smoothness")]
        public AtmosphereProperty<FloatValue> smoothness;
        /// <summary>
        /// Sets the base height (in meters) for the foreground fog.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the base height (in meters) for the foreground fog.")]
        [AtmosphereProperty(VarType.Float, "BaseHeight")]
        public AtmosphereProperty<FloatValue> baseHeight;
        /// <summary>
        /// Sets the base smoothness (in meters) for the foreground fog.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the base smoothness (in meters) for the foreground fog.")]
        [AtmosphereProperty(VarType.Float, "BaseSmoothness")]
        public AtmosphereProperty<FloatValue> baseSmoothness;
        /// <summary>
        /// Sets the distance (in meters) that the fog will transition from the height-based fog (foreground) to the angle-based fog (background).
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the distance (in meters) that the fog will transition from the height-based fog (foreground) to the angle-based fog (background).")]
        [AtmosphereProperty(VarType.Float, "TransitionDistance")]
        public AtmosphereProperty<FloatValue> transitionDistance;

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float time) {
            if (!active) return;
            densityMultiplier.SetValue(ref parameters.fogBaseDensityMultiplier, time);
            height.SetValue(ref parameters.fogBaseHeight, time);
            smoothness.SetValue(ref parameters.fogBaseSmoothness, time);
            baseHeight.SetValue(ref parameters.fogBaseBaseHeight, time);
            baseSmoothness.SetValue(ref parameters.fogBaseBaseSmoothness, time);
            transitionDistance.SetValue(ref parameters.fogBaseTransitionDistance, time);
        }

        public override void ResetToDefaults() {
        }

        public override void CopyModel(AtmosphereModel model) {
                densityMultiplier = model.fogBaseDensityMultiplier;
                height = model.fogBaseHeight;
                smoothness = model.fogBaseSmoothness;
                baseHeight = model.fogBaseBaseHeight;
                baseSmoothness = model.fogBaseBaseSmoothness;
                transitionDistance = model.fogBaseTransitionDistance;
        }

        public override void ApplyAsBiome(AtmosphereParameters parameters, float time, float weight) {
            if (!active || weight == 0) return;
            parameters.fogBaseDensityMultiplier.Lerp(densityMultiplier.GetValue(parameters.fogBaseDensityMultiplier, time), weight);
            parameters.fogBaseHeight.Lerp(height.GetValue(parameters.fogBaseHeight, time), weight);
            parameters.fogBaseSmoothness.Lerp(smoothness.GetValue(parameters.fogBaseSmoothness, time), weight);
            parameters.fogBaseBaseHeight.Lerp(baseHeight.GetValue(parameters.fogBaseBaseHeight, time), weight);
            parameters.fogBaseBaseSmoothness.Lerp(baseSmoothness.GetValue(parameters.fogBaseBaseSmoothness, time), weight);
            parameters.fogBaseTransitionDistance.Lerp(transitionDistance.GetValue(parameters.fogBaseTransitionDistance, time), weight);
        }

        public override void ApplyToModel(AtmosphereModel model) {
             if (!FeatureEnabledGlobally || !active) return;
            if (densityMultiplier.overrideValue)
                model.fogBaseDensityMultiplier = densityMultiplier;
            if (height.overrideValue)
                model.fogBaseHeight = height;
            if (smoothness.overrideValue)
                model.fogBaseSmoothness = smoothness;
            if (baseHeight.overrideValue)
                model.fogBaseBaseHeight = baseHeight;
            if (baseSmoothness.overrideValue)
                model.fogBaseBaseSmoothness = baseSmoothness;
            if (transitionDistance.overrideValue)
                model.fogBaseTransitionDistance = transitionDistance;
        }
    }


